/// <summary>
/// <c>METSalesDocumentPostingController</c> is a controller class to post sales document.
/// </summary>
public class METSalesDocumentPostingController extends METSysOperationServiceController
{
}

Method.Source:
/// <summary>
/// Contruct method
/// </summary>
/// <param name = "_args"> Args </param>
/// <param name = "_conShipmentId"> container shipment </param>
/// <param name = "_conDocStatus"> container document status </param>
/// <returns>Controller</returns>
public static METSalesDocumentPostingController construct(Args _args, container _conShipmentId = conNull(), container _conDocStatus = conNull())
{
    METSalesDocumentPostingController       controller;
    METSalesDocumentPostingDataContract     contract;


    controller = new METSalesDocumentPostingController(classStr(METSalesDocumentPostingService),
                                                    methodStr(METSalesDocumentPostingService, run),
                                                    SysOperationExecutionMode::Synchronous);

    contract    = controller.getDataContractObject() as METSalesDocumentPostingDataContract;
    contract.parmShipmentIdList(_conShipmentId);
    contract.parmDocStatusList(_conDocStatus);

    controller.parmDialogCaption("@MET:PostSalesDocument");
    return controller;
}

/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    METSalesDocumentPostingController     controller      = METSalesDocumentPostingController::construct(_args);

    controller.startOperation();
}
